-- Quests (validated by quest_v2_check; edit them later in the Game console › Quests).
select eldervale_private.quest_arc_put('a3c0b000-0004-4000-8000-000000000004',$q${"chain":"arc-tide","order":4,"published":true,"objectives":[],"key":"arc-tide-4","name":"The Harbourmaster’s Ledger","questPoints":3,"difficulty":"Experienced","length":"Long","giver":"a3c0a000-0004-4000-8000-000000000002","icon":"rope","requirements":{"quests":["arc-tide-3"],"qp":16,"skills":{"fishing":{"level":40,"boostable":false},"crafting":{"level":35,"boostable":false},"agility":{"level":30,"boostable":false}}},"description":"Somebody cut the ropes of Corrow’s warning bell. Agathe has kept every scrap of rope the sea gave back, and every one was cut with the same blade. She thinks the answer is in Saltglass, not under it.","dialogue":{"offer":[{"who":"npc","text":"Look at these ends. Every rope cut the same, one stroke, a left-handed blade."},{"who":"npc","text":"Harbourmaster Tidewell is left-handed. So was his father, and his father’s father. All harbourmasters, all the way back to Corrow."},{"who":"npc","text":"I do not want it to be him. Find out, before I have to mend that net too."}],"progress":[{"who":"npc","text":"Well? Is it the Tidewells?"}],"complete":[{"who":"npc","text":"Rope for the dive. And the truth, which is heavier."},{"who":"npc","text":"The Drowned Steps are open; the low tide will hold for you. Go and give the choir its rest."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"protected_tidewell":true},"lines":[{"who":"npc","text":"So he pays for the dive, the shrouds and the stones, and keeps his post. Hm. It is more than his family ever paid."},{"who":"npc","text":"The Drowned Steps are open. Go and give the choir its rest."}]}],"stages":[{"id":"dream","journal":"Agathe found that every bell-rope was cut by a left-handed blade, and the Tidewell harbourmasters, back to Corrow’s day, have all been left-handed. Little Tobin has been dreaming again.","objectives":[{"type":"talk","target":"a3c0a000-0004-4000-8000-000000000003","amount":1,"label":"Ask Little Tobin about his dream","dialogue":[{"who":"npc","text":"I dreamed about a man with the harbourmaster’s face. Old clothes. He cut the bell-ropes and took the silver bells away in a cart while it rained."},{"who":"npc","text":"He kept a book. A big one, with a fish on the front."}]}]},{"id":"office","journal":"Tobin dreamed of a man with Tidewell’s face cutting the bell-ropes and carting off the silver bells, writing it all in a big book with a fish on the cover. The harbour books are kept in the back room of the tackle shop. I need to get in there unseen.","objectives":[{"type":"visit","x":283,"z":336,"radius":3,"amount":1,"label":"Slip into the back room of the tackle shop"}]},{"id":"ledger","journal":"In the back room I found the oldest harbour ledger, with a fish on its cover, written in a script I cannot read. Scholar Ilse can.","onEnter":{"cutscene":"ledger"},"objectives":[{"type":"talk","target":"a3c0a000-0004-4000-8000-000000000006","amount":1,"label":"Have Ilse read the old harbour ledger","dialogue":[{"who":"npc","text":"“Sold: nine silver bells of Corrow, to the Birchford mint. Ropes cut, that the bell not ring, that the town not climb, that the bells be ours.”"},{"who":"npc","text":"Signed Osric Tidewell, harbourmaster. Two hundred years ago. The Tidewells built Saltglass on drowned silver."}]}]},{"id":"confront","journal":"The ledger proves it: Osric Tidewell cut the warning bell’s ropes and sold Corrow’s silver bells while the town drowned. Corwen Tidewell, his descendant, is harbourmaster today. I should confront him.","npc":"a3c0a000-0004-4000-8000-000000000001","objectives":[{"type":"talk","target":"a3c0a000-0004-4000-8000-000000000001","amount":1,"label":"Confront Harbourmaster Tidewell with the ledger","dialogue":[{"who":"npc","text":"I know what it says. Every Tidewell reads it on the day they take the harbour. And every one of us puts it back on the shelf."},{"who":"npc","text":"I am not proud. I am also not Osric. What will you do?"}]}],"dialogue":{"choice":[{"who":"npc","text":"Tell the whole landing, and I lose the harbour. Or let me pay for the dive, the shrouds and the stones, and make it right as best I can."}]},"choices":[{"id":"expose","label":"Saltglass deserves the truth. Tell them.","flags":{"exposed_tidewell":true},"dialogue":[{"who":"npc","text":"Then I will tell them myself, on the pier, tonight. It should come from a Tidewell."}]},{"id":"protect","label":"Pay for the dive and the burial. Keep your post.","flags":{"protected_tidewell":true},"dialogue":[{"who":"npc","text":"Every coin. And the stones will have their names. I swear it on the ledger."}]}]},{"id":"ropes","journal":"Whatever becomes of Tidewell, the choir is still singing under the bay. Agathe will lower me down the Drowned Steps at low tide if I bring her three coils of rope.","objectives":[{"type":"collect","target":"rope","amount":3,"label":"Bring Agathe three coils of rope for the dive"}]}],"cutscenes":{"ledger":{"name":"The fish-backed ledger","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0004-4000-8000-000000000002","distance":5,"height":2.2,"angle":30}},{"title":"The harbour ledger","subtitle":"Saltglass Landing","ms":2400},{"say":{"who":"npc","name":"Agathe the Net-Mender","text":"(Agathe, keeping watch by the door) Hurry. He counts the crates at the top of every hour. Every hour. The man is a clock."},"shot":{"around":"a3c0a000-0004-4000-8000-000000000002","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"steps":{"name":"The Drowned Steps","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0004-4000-8000-000000000002","distance":5,"height":2.2,"angle":30}},{"title":"The Drowned Steps","subtitle":"Saltglass Bay, at the lowest tide","ms":2400},{"say":{"who":"npc","name":"Agathe the Net-Mender","text":"There they are. Steps going down into the bay, where there should not be any. The sea is letting you in."},"shot":{"around":"a3c0a000-0004-4000-8000-000000000002","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"steps"},"journalDone":"Little Tobin’s dream led me to the oldest harbour ledger: Osric Tidewell cut the ropes of Corrow’s warning bell and sold its silver while the town drowned. I confronted his descendant, Harbourmaster Corwen Tidewell, and Agathe opened the Drowned Steps for a dive at the lowest tide.","journalVariants":[{"ifFlags":{"exposed_tidewell":true},"text":"Tidewell told the whole landing the truth, on the pier."},{"ifFlags":{"protected_tidewell":true},"text":"Tidewell kept his post and paid for the dive, the shrouds and the stones."}],"gold":1200,"xp":{"fishing":20000,"crafting":15000,"agility":12000},"lamps":[{"amount":15000,"minLevel":30,"label":"Harbour lamp (any skill of level 30+)"}],"unlocks":[{"type":"area","id":"area.tide-steps","label":"The Drowned Steps, Saltglass Bay"},{"type":"flag","id":"tide.ledger_read","label":"Saltglass knows who cut the ropes"},{"type":"dialogue","id":"dialogue.tide-tidewell-exposed","label":"Tidewell, no longer harbourmaster","npc":"a3c0a000-0004-4000-8000-000000000001","ifFlags":{"exposed_tidewell":true},"lines":[{"who":"npc","text":"They let me keep the uniform. Not the post. I mend nets for Agathe now. She is a harsh employer. It is fair."}]},{"type":"dialogue","id":"dialogue.tide-tidewell-protected","label":"Tidewell pays his debts","npc":"a3c0a000-0004-4000-8000-000000000001","ifFlags":{"protected_tidewell":true},"lines":[{"who":"npc","text":"The stonemason starts the names next week. Two hundred and twelve of them. I am paying by the letter. It is the best money my family ever spent."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0004-4000-8000-000000000005',$q${"chain":"arc-tide","order":5,"published":true,"objectives":[],"key":"arc-tide-5","name":"The Drowned Choir","questPoints":5,"difficulty":"Master","length":"Very long","giver":"a3c0a000-0004-4000-8000-000000000006","icon":"custom_qa_tidebell","requirements":{"quests":["arc-tide-1","arc-tide-2","arc-tide-3","arc-tide-4"],"qp":36,"skills":{"fishing":{"level":50,"boostable":false},"crafting":{"level":45,"boostable":false},"prayer":{"level":40,"boostable":false},"agility":{"level":40,"boostable":false}},"combat":60},"description":"At the lowest tide the Drowned Steps lead down into the chapel of Old Corrow, where the choir still sings and the Choirmistress still rings a bell with no rope. Scholar Ilse has the hymn. You have the nerve.","dialogue":{"offer":[{"who":"npc","text":"The hymn, the shrouds, the steps. Everything is ready except someone to carry it down."},{"who":"npc","text":"The Choirmistress rang the warning bell until the rope was cut. She is still ringing it. If she hears the hymn, perhaps she will stop."},{"who":"player","text":"And if she doesn’t?"},{"who":"npc","text":"Then she will not let you leave, and I will write a very sad book. Please do not make me write that book."}],"progress":[{"who":"npc","text":"The tide turns soon. Hurry, but do not drown."}],"complete":[{"who":"npc","text":"The warning bell of Corrow. It rings true. After two hundred years it rings true."},{"who":"npc","text":"Keep this tidebell, cast from the same silver; it will take you back to the Drowned Steps. And this staff, which Corrow’s choir-priests carried. It answers the sea."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"laid_to_rest":true},"lines":[{"who":"npc","text":"They are resting. I heard the bells stop at noon, one by one, like lamps going out."},{"who":"npc","text":"Keep this tidebell, and this staff of Corrow’s choir-priests. It answers the sea, and the sea owes you now."}]},{"stage":"complete","ifFlags":{"bells_broken":true},"lines":[{"who":"npc","text":"You broke the bells. The choir is free of them, and of the bay. The fishermen say the sea is very quiet. Too quiet, some say."},{"who":"npc","text":"Keep this tidebell, and this staff of Corrow’s choir-priests. It answers the sea."}]}],"stages":[{"id":"provisions","journal":"At the lowest tide the Drowned Steps lead down into Old Corrow’s chapel. Agathe will pack food for the dive if I bring her five cooked lobsters.","npc":"a3c0a000-0004-4000-8000-000000000002","objectives":[{"type":"collect","target":"lobster","amount":5,"label":"Bring Agathe five cooked lobsters for the dive"}],"dialogue":{"advance":[{"who":"npc","text":"Lobsters, shrouds, rope, hymn. And you. Down you go, and come back up, mind. I have run out of thread for mending people."}]}},{"id":"steps","journal":"Agathe packed for the dive. Time to go down the Drowned Steps into the nave of Old Corrow.","onEnter":{"cutscene":"nave"},"objectives":[{"type":"visit","x":3824,"z":3000,"radius":7,"amount":1,"label":"Descend the Drowned Steps into the nave"}]},{"id":"wardens","journal":"The nave is guarded by the bell-wardens of Corrow, who never heard that the ropes were cut.","objectives":[{"type":"event","event":"death","targets":["a3c0a000-0004-4000-9000-000000000006","a3c0a000-0004-4000-9000-000000000007"],"amount":2,"label":"Lay the bell-wardens to rest"}]},{"id":"alcoves","journal":"Past the wardens are three bell alcoves, their bells hanging silent. The hymn goes salt, bell, still water: the salt-crusted bell to the west, the great bell to the east, the still bell nearest the apse. I should ring them in the hymn’s order.","objectives":[{"type":"visit","x":3844,"z":2990,"radius":2.5,"amount":1,"label":"Ring the salt-crusted bell"},{"type":"visit","x":3852,"z":2990,"radius":2.5,"amount":1,"label":"Ring the great bell"},{"type":"visit","x":3848,"z":2999,"radius":2.5,"amount":1,"label":"Ring the still bell"}]},{"id":"choirmistress","journal":"The three bells rang the hymn, and the apse door opened. The Choirmistress is inside, ringing a bell with no rope, and she has noticed me.","onEnter":{"cutscene":"choirmistress"},"objectives":[{"type":"kill","target":"a3c0a000-0004-4000-9000-000000000008","amount":1,"label":"Still the Choirmistress Below"},{"type":"have","target":"custom_qa_corrow_bell","amount":1,"label":"Take the Corrow warning bell"}]},{"id":"rest","journal":"The Choirmistress is still. In the quiet, the voices of the whole drowned choir spoke at once from the apse, asking what comes next.","npc":"a3c0a000-0004-4000-8000-000000000007","objectives":[{"type":"talk","target":"a3c0a000-0004-4000-8000-000000000007","amount":1,"label":"Answer the Echo of Old Corrow","dialogue":[{"who":"npc","text":"We sang to the tide, and the tide kept its bargain. Then the bell did not ring, and we sang all the way down."},{"who":"npc","text":"We are tired. But the bells hold us. Ring us to sleep, or break the bells and let us go where we will."}]}],"dialogue":{"choice":[{"who":"npc","text":"Choose, warm one. We have waited long enough to be patient one moment more."}]},"choices":[{"id":"rest","label":"Sing the hymn of salt to the end, and rest.","flags":{"laid_to_rest":true},"dialogue":[{"who":"npc","text":"Salt... bell... still water. Yes. Still water. Thank you. Thank you. Thank..."}]},{"id":"break","label":"Break the bells. Go where you will.","flags":{"bells_broken":true},"dialogue":[{"who":"npc","text":"Free! The tide is wide and the sea is deep. Goodbye, warm one. Goodbye, Saltglass!"}]}]},{"id":"surface","journal":"The choir has its answer. The Corrow warning bell should go back to Scholar Ilse at Saltglass Landing.","objectives":[{"type":"collect","target":"custom_qa_corrow_bell","amount":1,"label":"Give the warning bell to Scholar Ilse"}]}],"cutscenes":{"nave":{"name":"The drowned nave","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0004-4000-8000-000000000006","distance":5,"height":2.2,"angle":30}},{"title":"The Sunken Choir","subtitle":"Under Saltglass Bay","ms":2400},{"say":{"who":"npc","name":"Scholar Ilse Quillon","text":"(Ilse’s voice, from the top of the steps) If you hear singing, that is them. If you hear me singing, that is me panicking."},"shot":{"around":"a3c0a000-0004-4000-8000-000000000006","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"choirmistress":{"name":"The Choirmistress Below","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0004-4000-8000-000000000007","distance":5,"height":2.2,"angle":30}},{"title":"The Choirmistress Below","subtitle":"The apse of Old Corrow","ms":2400},{"say":{"who":"npc","name":"Echo of Old Corrow","text":"(Two hundred voices, singing the first line of the hymn of salt. One voice, higher than the rest, refuses to stop ringing.)"},"shot":{"around":"a3c0a000-0004-4000-8000-000000000007","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"quiet":{"name":"Still water","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0004-4000-8000-000000000003","distance":5,"height":2.2,"angle":30}},{"title":"Still water","subtitle":"Saltglass Landing","ms":2400},{"say":{"who":"npc","name":"Little Tobin","text":"The bells stopped. I can hear the sea now. Just the sea. It is nice."},"shot":{"around":"a3c0a000-0004-4000-8000-000000000003","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"quiet"},"journalDone":"I went down the Drowned Steps into the Sunken Choir, laid its bell-wardens to rest, rang the alcove bells in the order of the hymn of salt and stilled the Choirmistress Below. The drowned choir of Old Corrow has its answer. The Tidebell will always bring me back to the Drowned Steps.","journalVariants":[{"ifFlags":{"laid_to_rest":true},"text":"I sang the choir to rest. The bells stopped at noon, one by one."},{"ifFlags":{"bells_broken":true},"text":"I broke the bells and the choir went out into the sea, free."}],"gold":5000,"xp":{"fishing":60000,"crafting":40000,"prayer":35000,"magic":25000},"items":{"custom_qa_tidebell":1,"weapon:tidecallerStaff":1},"lamps":[{"amount":20000,"minLevel":40,"label":"Tidebell lamp (any skill of level 40+)"}],"unlocks":[{"type":"teleport","id":"teleport.drowned-steps","label":"Tidebell of Corrow: the Drowned Steps, Saltglass","x":322,"z":356},{"type":"area","id":"area.tide-loft","label":"The bell loft: Bell-Salvager Odile and the Choirmistress’s Lament (harder mode)"},{"type":"area","id":"lair:gloomweb_nest","label":"Gloomweb Nest: with the choir silent, something in Gloom hollow wakes"},{"type":"flag","id":"tide.choir_answered","label":"The drowned choir of Corrow is answered"},{"type":"dialogue","id":"dialogue.tide-ilse-rest","label":"Ilse writes the happy book","npc":"a3c0a000-0004-4000-8000-000000000006","ifFlags":{"laid_to_rest":true},"lines":[{"who":"npc","text":"I am writing the book. It has a happy ending. I keep checking, in case it changes."}]},{"type":"dialogue","id":"dialogue.tide-ilse-free","label":"Ilse writes the strange book","npc":"a3c0a000-0004-4000-8000-000000000006","ifFlags":{"bells_broken":true},"lines":[{"who":"npc","text":"Fishermen swear they hear singing far out past the reef, going away. I am writing it all down. Nobody will believe it. I do."}]},{"type":"dialogue","id":"dialogue.tide-agathe-5","label":"Agathe’s nets come up whole","npc":"a3c0a000-0004-4000-8000-000000000002","lines":[{"who":"npc","text":"Not one torn net all month. I am bored stiff. It is wonderful."}]},{"type":"dialogue","id":"dialogue.tide-moss-5","label":"Moss heard the bells stop","npc":"a3c0a000-0004-4000-8000-000000000004","lines":[{"who":"npc","text":"Heard it all the way out here: the bells, stopping. Then something in Gloom hollow stopped holding its breath. Mind the webs, now."}]}]}$q$::jsonb);

commit;
